uniform float speed : 0.0 .. 5.0 = 1.0;
uniform float waves : 0.5 .. 8.0 = 3.0;
uniform float sat   : 0.0 .. 1.0 = 0.9;
uniform float depth : 0.1 .. 2.0 = 1.0;
state fixed ph;
state fixed k;
state fixed s;
void update() {
  ph = fract(ph + fixed(dt * speed * 0.0625));   // phases in TURNS, advanced once per frame
  k = fixed(waves);
  s = fixed(sat);
}
vec3 shade(Led led) {
  // radial wave: distance along helix + phase scroll
  fixed r = fixed(led.pos.x) * fixed(led.pos.x) + fixed(led.pos.z) * fixed(led.pos.z);
  fixed h = fixed(led.pos.y);
  // radial distance from centre, scroll waves along height
  fixed rd = sqrt(r);  // float sqrt for radial distance
  // scroll effect
  fixed wave = sin(fixed(led.uv.y) * k + ph) * depth;
  // convert radial+height to a phase-based caustics index
  fixed idx = fract(rd * fixed(20.0) + wave * fixed(0.5) + ph * fixed(0.25));
  // shimmer: rapid jitter on the index
  fixed shimmer = sin(fixed(led.idx) * fixed(12.9898) + ph * fixed(73.0)) * fixed(0.02);
  idx = idx + shimmer;
  // map to hue, constant saturation/value
  return hsv2rgb(fract(idx), s, fixed(1.0));
}
